local ExtraStats = {
  Shield = "https://steamusercontent-a.akamaihd.net/ugc/1699533601343908790/D3F0AE388084459C9668C4D7D648B9C87CB3598A/",
  Retaliate = "https://steamusercontent-a.akamaihd.net/ugc/1699533601343909793/FC9B2B03FE39B7693596820A25A2712B733585EB/",
  Attack = "https://steamusercontent-a.akamaihd.net/ugc/1699533601343910452/EBEEF4F2DD1735088BD6C74A0CFA29532D440ED8/",
}

function onLoad()
  -- Global must finish loading before its API functions exist.
  Wait.frames(function()
    for name, image in pairs(ExtraStats) do
      Global.call("api_condition_registerCondition", { name, { image = image, max = 20 } })
    end
  end, 30)
end
